/**
 * Agenda — multi-surface scheduled agent runs.
 *
 * v0 surface: list of the user's tasks + a simple "New task" form. Run-now
 * triggers an immediate fire by setting next_due_at = now and waiting for
 * the SW scanner to pick it up; the notification is the user-facing handoff
 * back into chat (full programmatic execution is v1).
 *
 * Highlighted-task focus on mount: when the SW handles a notification click
 * it stashes `matrx.agenda.focus_task_id` in chrome.storage.session — we
 * read that here and scroll the matching row into view.
 */

import { useChatStream } from '@/hooks/use-chat-stream';
import { isValidCron, nextCronTime } from '@/lib/agenda/cron';
import {
  type AgendaTask,
  type AuthMode,
  type SurfaceTarget,
  type TriggerType,
  createTask,
  deleteTask,
  listMyTasks,
  updateTask,
} from '@/lib/agenda/queries';
import { isTaskRunning, runTask } from '@/lib/agenda/runner';
import { log } from '@/lib/debug/log';
import {
  isOrganizationNoMembershipsError,
  isOrganizationNotSelectedError,
} from '@/lib/org/active-org';
import { cn } from '@/lib/utils';
import { ConfirmDialog } from '@ai-matrx/design-system';
import {
  Button,
  BasicInput as Input,
  Label,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@ai-matrx/design-system';
// THE package formatters (`@ai-matrx/kit/format`, duplication census H1
// 2026-09-07): the fleet had ~35 duration, ~18 relative-time and ~20 byte-size
// twins with no correct owner until kit became one.
import { formatDurationMs } from '@ai-matrx/kit/format';
import { Calendar, Clock, Heart, Pause, Play, PlayCircle, Plus, Trash2, Zap } from 'lucide-react';
import { useCallback, useEffect, useState } from 'react';

const FOCUS_KEY = 'matrx.agenda.focus_task_id';

export function AgendaView() {
  const [tasks, setTasks] = useState<AgendaTask[] | null>(null);
  const [showForm, setShowForm] = useState(false);
  const [focusTaskId, setFocusTaskId] = useState<string | null>(null);
  const { send } = useChatStream();

  const refresh = useCallback(async () => {
    const list = await listMyTasks();
    setTasks(list);
  }, []);

  useEffect(() => {
    void refresh();
    void chrome.storage.session?.get([FOCUS_KEY]).then((r) => {
      const id = r[FOCUS_KEY];
      if (typeof id === 'string') {
        setFocusTaskId(id);
        void chrome.storage.session?.remove(FOCUS_KEY);
      }
    });
  }, [refresh]);

  // Auto-run focused task when its auth_mode is 'auto'. The SW notification
  // click flow lands the user here with focus_task_id set; for ask-mode
  // tasks we just highlight, for auto-mode we go.
  useEffect(() => {
    if (!focusTaskId || !tasks) return;
    const task = tasks.find((t) => t.id === focusTaskId);
    if (!task) return;
    if (task.auth_mode === 'auto' && task.enabled && !isTaskRunning(task.id)) {
      // 'auto': this fires from a mount effect reacting to a focus id restored
      // from session storage, not from a control the person pressed on this
      // screen. An effect-driven send is automation even when a notification
      // click led here.
      void runTask(task, send, 'auto').then(() => void refresh());
    }
  }, [focusTaskId, tasks, send, refresh]);

  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-center justify-between border-b border-border/50 px-3 py-2">
        <div className="flex items-center gap-2 text-sm font-medium">
          <Calendar className="size-4" />
          Agenda
          <span className="font-mono text-[10px] tabular-nums text-muted-foreground">
            {tasks?.length ?? '—'}
          </span>
        </div>
        <Button
          size="sm"
          variant="secondary"
          className="h-7 gap-1 px-2 text-xs"
          onClick={() => setShowForm((s) => !s)}
        >
          <Plus className="size-3.5" />
          New task
        </Button>
      </div>

      {showForm && (
        <NewTaskForm
          onCancel={() => setShowForm(false)}
          onCreated={() => {
            setShowForm(false);
            void refresh();
          }}
        />
      )}

      <div className="flex-1 overflow-y-auto">
        {tasks === null ? (
          <div className="px-3 py-8 text-center text-xs text-muted-foreground">Loading…</div>
        ) : tasks.length === 0 ? (
          <div className="px-3 py-8 text-center text-xs text-muted-foreground">
            No scheduled tasks yet. Click <strong>New task</strong> to add one.
          </div>
        ) : (
          <ul className="divide-y divide-border/50">
            {tasks.map((task) => (
              <TaskRow
                key={task.id}
                task={task}
                highlighted={task.id === focusTaskId}
                onChanged={refresh}
                send={send}
              />
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

// ─── Row ────────────────────────────────────────────────────────────────────

function TaskRow({
  task,
  highlighted,
  onChanged,
  send,
}: {
  task: AgendaTask;
  highlighted: boolean;
  onChanged: () => Promise<void>;
  send: ReturnType<typeof useChatStream>['send'];
}) {
  const [working, setWorking] = useState<'run' | 'toggle' | 'delete' | null>(null);
  const [deleteOpen, setDeleteOpen] = useState(false);

  const runNow = async () => {
    setWorking('run');
    try {
      // Fires the task through the chat stream pipeline. Switches the
      // sidepanel to the chat tab so the user sees it run.
      // 'user': the Run-now button — a direct press on this row.
      await runTask(task, send, 'user');
      log.info('sys', `agenda: "${task.title}" running`);
    } finally {
      setWorking(null);
      await onChanged();
    }
  };

  const toggleEnabled = async () => {
    setWorking('toggle');
    try {
      await updateTask(task.id, { enabled: !task.enabled });
    } finally {
      setWorking(null);
      await onChanged();
    }
  };

  const performRemove = async () => {
    setDeleteOpen(false);
    setWorking('delete');
    try {
      await deleteTask(task.id);
    } finally {
      setWorking(null);
      await onChanged();
    }
  };

  const isHeartbeat = task.trigger_type === 'heartbeat';
  const Icon = isHeartbeat ? Heart : task.trigger_type === 'cron' ? Calendar : Clock;

  return (
    <li
      className={[
        'flex items-start gap-2 px-3 py-2.5 transition-colors',
        highlighted ? 'bg-amber-500/10' : '',
        task.enabled ? '' : 'opacity-50',
      ].join(' ')}
    >
      <Icon className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
      <div className="min-w-0 flex-1">
        <div className="truncate text-sm font-medium">{task.title}</div>
        <div className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[10px] font-mono text-muted-foreground">
          <span className="rounded bg-secondary/40 px-1.5 py-0.5">{task.trigger_type}</span>
          <span className="rounded bg-secondary/40 px-1.5 py-0.5">{task.auth_mode}</span>
          {task.surfaces.map((s) => (
            <span key={s} className="rounded bg-secondary/40 px-1.5 py-0.5">
              {s}
            </span>
          ))}
          {task.next_due_at && (
            <span title={task.next_due_at}>· next {formatDueDistance(task.next_due_at)}</span>
          )}
        </div>
        {task.description && (
          <div className="mt-1 line-clamp-2 text-xs text-muted-foreground">{task.description}</div>
        )}
      </div>
      <div className="flex shrink-0 items-center gap-0.5">
        <Button
          size="sm"
          variant="ghost"
          className="size-7 p-0"
          title="Run now"
          disabled={!!working}
          onClick={runNow}
        >
          {working === 'run' ? (
            <Zap className="size-3.5 animate-pulse" />
          ) : (
            <PlayCircle className="size-3.5" />
          )}
        </Button>
        <Button
          size="sm"
          variant="ghost"
          className="size-7 p-0"
          title={task.enabled ? 'Pause' : 'Resume'}
          disabled={!!working}
          onClick={toggleEnabled}
        >
          {task.enabled ? <Pause className="size-3.5" /> : <Play className="size-3.5" />}
        </Button>
        <Button
          size="sm"
          variant="ghost"
          className="size-7 p-0 text-destructive"
          title="Delete"
          disabled={!!working}
          onClick={() => setDeleteOpen(true)}
        >
          <Trash2 className="size-3.5" />
        </Button>
      </div>
      <ConfirmDialog
        open={deleteOpen}
        onOpenChange={(next) => {
          if (!next) setDeleteOpen(false);
        }}
        title={`Delete "${task.title}"?`}
        // The consequence, not a restated question: this is a hard row delete
        // and the FKs cascade the task's triggers AND its whole run history
        // away with it. Pause sits next to Delete, so the confirmation names
        // it as the keep-what-I-have choice.
        description={
          <>
            <span className="block">
              The schedule and every run this task has recorded are permanently deleted. This cannot
              be undone.
            </span>
            <span className="mt-2 block">
              To stop it running without losing its history, cancel and use Pause instead.
            </span>
          </>
        }
        confirmLabel="Delete"
        variant="destructive"
        busy={working === 'delete'}
        onConfirm={() => void performRemove()}
      />
    </li>
  );
}

// ─── New task form ──────────────────────────────────────────────────────────

function NewTaskForm({ onCancel, onCreated }: { onCancel: () => void; onCreated: () => void }) {
  const [title, setTitle] = useState('');
  const [prompt, setPrompt] = useState('');
  const [triggerType, setTriggerType] = useState<TriggerType>('one-shot');
  const [oneShotAt, setOneShotAt] = useState(() => {
    const d = new Date(Date.now() + 5 * 60_000);
    return new Date(d.getTime() - d.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
  });
  const [intervalSec, setIntervalSec] = useState(3600);
  const [cronExpr, setCronExpr] = useState('0 9 * * *');
  // context-match config — at least one of these must be set for the trigger
  // to ever fire.
  const [matchHostname, setMatchHostname] = useState('');
  const [matchUrlPattern, setMatchUrlPattern] = useState('');
  const [authMode, setAuthMode] = useState<AuthMode>('ask');
  const [surface, setSurface] = useState<SurfaceTarget>('any');
  const [submitting, setSubmitting] = useState(false);
  // A failed create says why, with the remedy when there is one — it used to
  // go to the debug log only, so the form just sat there (law 4).
  const [createError, setCreateError] = useState<string | null>(null);

  // A cron task needs a parseable expression; a context-match task needs at
  // least one condition — otherwise it would be created but could never fire.
  const triggerValid =
    triggerType !== 'cron'
      ? triggerType !== 'context-match' ||
        matchHostname.trim().length > 0 ||
        matchUrlPattern.trim().length > 0
      : isValidCron(cronExpr);

  const submit = async () => {
    if (!title.trim() || !prompt.trim() || !triggerValid) return;
    setSubmitting(true);
    setCreateError(null);
    try {
      const triggerConfig =
        triggerType === 'one-shot'
          ? { type: 'one-shot' as const, at: new Date(oneShotAt).toISOString() }
          : triggerType === 'interval'
            ? { type: 'interval' as const, every_seconds: intervalSec }
            : triggerType === 'heartbeat'
              ? { type: 'heartbeat' as const, every_seconds: intervalSec }
              : triggerType === 'context-match'
                ? {
                    type: 'context-match' as const,
                    ...(matchHostname.trim() ? { hostname: matchHostname.trim() } : {}),
                    ...(matchUrlPattern.trim() ? { url_pattern: matchUrlPattern.trim() } : {}),
                  }
                : { type: 'cron' as const, expression: cronExpr.trim() };
      await createTask({
        title: title.trim(),
        prompt: prompt.trim(),
        trigger_type: triggerType,
        trigger_config: triggerConfig,
        auth_mode: authMode,
        surfaces: [surface],
      });
      onCreated();
    } catch (err) {
      log.error('sys', 'agenda: createTask failed', err);
      setCreateError(
        isOrganizationNotSelectedError(err) || isOrganizationNoMembershipsError(err)
          ? err.remedy
          : `The task was not created: ${(err as Error).message}`,
      );
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-2 border-b border-border/50 bg-secondary/20 px-3 py-3">
      <div className="space-y-1">
        <Label htmlFor="agenda-title" className="text-xs">
          Title
        </Label>
        <Input
          id="agenda-title"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Daily Gmail triage"
          className="h-8 text-xs"
        />
      </div>
      <div className="space-y-1">
        <Label htmlFor="agenda-prompt" className="text-xs">
          Prompt
        </Label>
        <textarea
          id="agenda-prompt"
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Open Gmail and summarize all unread email from today."
          rows={3}
          className="w-full resize-y rounded-md border-0 bg-background px-2 py-1.5 text-xs focus:outline-none focus-visible:ring-1 focus-visible:ring-ring"
        />
      </div>
      <div className="grid grid-cols-2 gap-2">
        <div className="space-y-1">
          <Label className="text-xs">Trigger</Label>
          <Select value={triggerType} onValueChange={(v) => setTriggerType(v as TriggerType)}>
            <SelectTrigger className="h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="one-shot">One-shot</SelectItem>
              <SelectItem value="interval">Interval</SelectItem>
              <SelectItem value="heartbeat">Heartbeat</SelectItem>
              <SelectItem value="cron">Cron</SelectItem>
              <SelectItem value="context-match">On-match</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-1">
          <Label className="text-xs">Auth</Label>
          <Select value={authMode} onValueChange={(v) => setAuthMode(v as AuthMode)}>
            <SelectTrigger className="h-8 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="ask">Ask before running</SelectItem>
              <SelectItem value="auto">Run automatically</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
      {triggerType === 'one-shot' && (
        <div className="space-y-1">
          <Label htmlFor="agenda-at" className="text-xs">
            Run at
          </Label>
          <Input
            id="agenda-at"
            type="datetime-local"
            value={oneShotAt}
            onChange={(e) => setOneShotAt(e.target.value)}
            className="h-8 text-xs"
          />
        </div>
      )}
      {(triggerType === 'interval' || triggerType === 'heartbeat') && (
        <div className="space-y-1">
          <Label htmlFor="agenda-interval" className="text-xs">
            Every (seconds)
          </Label>
          <Input
            id="agenda-interval"
            type="number"
            min={60}
            value={intervalSec}
            onChange={(e) => setIntervalSec(Number.parseInt(e.target.value, 10) || 60)}
            className="h-8 text-xs"
          />
        </div>
      )}
      {triggerType === 'cron' && (
        <div className="space-y-1">
          <Label htmlFor="agenda-cron" className="text-xs">
            Cron expression
          </Label>
          <Input
            id="agenda-cron"
            value={cronExpr}
            onChange={(e) => setCronExpr(e.target.value)}
            placeholder="0 9 * * *"
            className={cn(
              'h-8 font-mono text-xs',
              !isValidCron(cronExpr) && 'border-destructive focus-visible:ring-destructive',
            )}
          />
          <p className="text-[10px] text-muted-foreground">
            {isValidCron(cronExpr)
              ? `Next: ${nextCronTime(cronExpr)?.toLocaleString() ?? '—'} (your timezone)`
              : 'min hour day-of-month month day-of-week — e.g. "0 9 * * 1-5"'}
          </p>
        </div>
      )}
      {triggerType === 'context-match' && (
        <div className="space-y-2">
          <div className="space-y-1">
            <Label htmlFor="agenda-match-host" className="text-xs">
              Hostname contains
            </Label>
            <Input
              id="agenda-match-host"
              value={matchHostname}
              onChange={(e) => setMatchHostname(e.target.value)}
              placeholder="mail.google.com"
              className="h-8 text-xs"
            />
          </div>
          <div className="space-y-1">
            <Label htmlFor="agenda-match-url" className="text-xs">
              URL matches (regex)
            </Label>
            <Input
              id="agenda-match-url"
              value={matchUrlPattern}
              onChange={(e) => setMatchUrlPattern(e.target.value)}
              placeholder="^https://github\\.com/.+/pull/\\d+"
              className="h-8 font-mono text-xs"
            />
          </div>
          <p className="text-[10px] text-muted-foreground">
            Fires when your active tab matches. Set at least one condition. Re-fires at most once
            every 10 min per task while the match holds.
          </p>
        </div>
      )}
      <div className="space-y-1">
        <Label className="text-xs">Surface</Label>
        <Select value={surface} onValueChange={(v) => setSurface(v as SurfaceTarget)}>
          <SelectTrigger className="h-8 text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="any">Any surface</SelectItem>
            <SelectItem value="chrome-extension-chat">Chrome extension</SelectItem>
            <SelectItem value="desktop">Desktop app</SelectItem>
            <SelectItem value="web">Web app</SelectItem>
            <SelectItem value="mobile">Mobile</SelectItem>
            <SelectItem value="sandbox">Sandbox</SelectItem>
          </SelectContent>
        </Select>
      </div>
      {createError && (
        <p role="alert" className="text-xs text-destructive">
          {createError}
        </p>
      )}
      <div className="flex items-center justify-end gap-2 pt-1">
        <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={onCancel}>
          Cancel
        </Button>
        <Button
          size="sm"
          className="h-7 text-xs"
          disabled={submitting || !title.trim() || !prompt.trim() || !triggerValid}
          onClick={submit}
        >
          {submitting ? 'Creating…' : 'Create task'}
        </Button>
      </div>
    </div>
  );
}

/**
 * How far away a DUE DATE is, in both directions: "in 3h 5m" for the future and
 * "3d 4h ago" for the past. Deliberately not `@ai-matrx/kit/format`'s
 * `formatRelativeTime`, which answers "how long ago?" and reads a future
 * timestamp as "just now" — an agenda that says "just now" about tomorrow's
 * deadline is a screen telling a lie. Renamed 2026-09-07 (census H1) so the
 * name says which question it answers.
 *
 * The SPAN itself is the package's (`coarse` — the dense-cell voice), and this
 * is only the direction wrapper the package deliberately has no opinion about.
 * `round: "down"` because a future due date IS a countdown: "in 3h" with 2h31m
 * left promises the user half an hour they do not have.
 */
function formatDueDistance(iso: string): string {
  const dueMs = new Date(iso).getTime() - Date.now();
  const abs = Math.abs(dueMs);
  if (abs < 60_000) return dueMs >= 0 ? 'now' : 'just now';
  const span = formatDurationMs(abs, { style: 'coarse', round: 'down' });
  return dueMs >= 0 ? `in ${span}` : `${span} ago`;
}
